-- ====================================================
-- VGS Finance & Loans Management System - Full Schema & Seed
-- Hostinger MySQL / phpMyAdmin Ready
-- Database: u218019073_Vgsfinance
-- ====================================================

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `categories` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `icon` VARCHAR(255) DEFAULT NULL,
  `description` TEXT DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `products` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `categoryId` VARCHAR(255) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `tagline` TEXT DEFAULT NULL,
  `interestRate` FLOAT NOT NULL,
  `minAmount` DOUBLE NOT NULL,
  `maxAmount` DOUBLE NOT NULL,
  `minTenure` INT NOT NULL,
  `maxTenure` INT NOT NULL,
  `processingFee` VARCHAR(255) DEFAULT NULL,
  `eligibility` TEXT DEFAULT NULL,
  `documentsRequired` TEXT DEFAULT NULL,
  `features` TEXT DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_categoryId` (`categoryId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `partners` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `code` VARCHAR(255) NOT NULL,
  `type` VARCHAR(255) DEFAULT NULL,
  `logoText` VARCHAR(255) DEFAULT NULL,
  `maxLtv` VARCHAR(255) DEFAULT NULL,
  `approvalRate` VARCHAR(255) DEFAULT NULL,
  `features` TEXT DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `testimonials` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `loanType` VARCHAR(255) DEFAULT NULL,
  `amount` VARCHAR(255) DEFAULT NULL,
  `city` VARCHAR(255) DEFAULT NULL,
  `rating` INT DEFAULT 5,
  `comment` TEXT DEFAULT NULL,
  `avatar` VARCHAR(255) DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `customers` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `fullName` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(255) NOT NULL UNIQUE,
  `email` VARCHAR(255) DEFAULT NULL,
  `city` VARCHAR(255) DEFAULT NULL,
  `employmentType` VARCHAR(255) DEFAULT NULL,
  `monthlyIncome` DOUBLE DEFAULT 0,
  `cibilScore` INT DEFAULT NULL,
  `kycStatus` VARCHAR(255) DEFAULT 'PENDING',
  `totalLoansEnquired` INT DEFAULT 0,
  `totalAmountEnquired` DOUBLE DEFAULT 0,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `leads` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `customerId` VARCHAR(255) DEFAULT NULL,
  `customerName` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `city` VARCHAR(255) DEFAULT NULL,
  `employmentType` VARCHAR(255) DEFAULT NULL,
  `monthlyIncome` DOUBLE DEFAULT NULL,
  `productName` VARCHAR(255) NOT NULL,
  `requestedAmount` DOUBLE NOT NULL,
  `tenureMonths` INT NOT NULL,
  `status` VARCHAR(255) DEFAULT 'NEW_ENQUIRY',
  `priority` VARCHAR(255) DEFAULT 'HIGH',
  `leadSource` VARCHAR(255) DEFAULT 'Website Portal Enquiry',
  `assignedTo` VARCHAR(255) DEFAULT NULL,
  `partnerBankId` VARCHAR(255) DEFAULT NULL,
  `assignedBank` VARCHAR(255) DEFAULT 'Not Assigned Yet',
  `bankApplicationNo` VARCHAR(255) DEFAULT NULL,
  `bankProcessStage` VARCHAR(255) DEFAULT 'NOT_ROUTED',
  `sanctionedAmount` DOUBLE DEFAULT NULL,
  `sanctionedRate` FLOAT DEFAULT NULL,
  `bankRemarks` TEXT DEFAULT NULL,
  `disbursedDate` VARCHAR(255) DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_customerId` (`customerId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `follow_ups` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `leadId` VARCHAR(255) NOT NULL,
  `date` VARCHAR(255) DEFAULT NULL,
  `notes` TEXT DEFAULT NULL,
  `nextDate` VARCHAR(255) DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_leadId` (`leadId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `loans` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `leadId` VARCHAR(255) DEFAULT NULL,
  `customerId` VARCHAR(255) DEFAULT NULL,
  `loanType` VARCHAR(255) DEFAULT NULL,
  `amount` DOUBLE DEFAULT NULL,
  `interestRate` FLOAT DEFAULT NULL,
  `tenureMonths` INT DEFAULT NULL,
  `status` VARCHAR(255) DEFAULT 'ACTIVE',
  `disbursalDate` VARCHAR(255) DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `admin_users` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `username` VARCHAR(255) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `fullName` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `phone` VARCHAR(255) DEFAULT NULL,
  `role` VARCHAR(255) DEFAULT 'LOAN_OFFICER',
  `isActive` TINYINT(1) DEFAULT 1,
  `lastLogin` VARCHAR(255) DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `website_contents` (
  `id` VARCHAR(255) NOT NULL PRIMARY KEY,
  `key` VARCHAR(255) NOT NULL UNIQUE,
  `content` TEXT DEFAULT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

